      es: "La Reserva Eduardo Avaroa es conocida por sus paisajes surreales, géiseres activos y lagunas coloridas llenas de flamencos.",
      pt: "A Reserva Eduardo Avaroa é conhecida pelas suas paisagens surreais, géiseres ativos e lagoas coloridas repletas de flamingos.",
      fr: "La réserve Eduardo Avaroa est célèbre pour ses paysages surréalistes, ses geysers actifs et ses lagunes colorées peuplées de flamants roses.",
