      es: "En las profundidades de la cuenca del Amazonas, cooperativas de pequeños agricultores cultivan cacao orgánico de alta calidad, apoyando la agroforestería sostenible.",
      pt: "Nas profundezas da bacia amazônica, cooperativas de pequenos agricultores cultivam cacau orgânico de alta qualidade, apoiando a agroflorestal sustentável.",
      fr: "Au cœur du bassin amazonien, des coopératives de petits agriculteurs cultivent du cacao biologique de haute qualité, soutenant ainsi l'agroforesterie durable.",
